const $ = (selector) => document.querySelector(selector);
if ('serviceWorker' in navigator && location.protocol !== 'file:') {
  const isLocalPreview = location.hostname === '127.0.0.1' || location.hostname === 'localhost';
  window.addEventListener('load', () => {
    if (isLocalPreview) navigator.serviceWorker.getRegistrations().then((registrations) => Promise.all(registrations.map((registration) => registration.unregister())));
    else navigator.serviceWorker.register('./service-worker.js').catch(() => {});
  });
}
