const roleKeyByLabel = Object.freeze({ Locataire: 'tenant', Propriétaire: 'owner', Professionnel: 'professional' });
const roleLabelByKey = Object.freeze({ tenant: 'Locataire', owner: 'Propriétaire', professional: 'Professionnel' });
function roleKeyFromLabel(label) { return roleKeyByLabel[label] || 'tenant'; }
function roleLabelFromKey(role) { return roleLabelByKey[role] || 'Locataire'; }
function readLocalList(key) { try { const value = JSON.parse(localStorage.getItem(key)); return Array.isArray(value) ? value : []; } catch { return []; } }
function writeLocalList(key, value) { localStorage.setItem(key, JSON.stringify(value)); }
function refreshDossierCounts() { $('#documentCount').textContent = $('#documentList').children.length; $('#accessCount').textContent = $('#accessList').children.length; }
function appendSavedDocument(storedDocument) {
  const row = document.createElement('article'); row.className = 'document-row';
  const icon = document.createElement('span'); icon.className = `file-icon ${storedDocument.extension === 'JPG' ? 'jpg' : 'pdf'}`; icon.textContent = storedDocument.extension || 'PDF';
  const main = document.createElement('div'); main.className = 'doc-main'; const title = document.createElement('strong'); title.textContent = storedDocument.name; const detail = document.createElement('span'); detail.textContent = 'Ajoute localement - en attente de verification'; main.append(title, detail);
  const status = document.createElement('span'); status.className = 'pending'; status.textContent = 'A verifier'; const more = document.createElement('button'); more.className = 'more'; more.setAttribute('aria-label', 'Options'); more.dataset.doc = storedDocument.name; more.textContent = '...'; row.append(icon, main, status, more); $('#documentList').append(row);
}
function appendSavedShare(share) {
  const row = document.createElement('article'); row.className = 'access-row'; row.dataset.person = share.name; row.dataset.shareId = share.id || '';
  const avatar = document.createElement('span'); avatar.className = 'avatar'; avatar.textContent = share.initials; const main = document.createElement('div'); const title = document.createElement('strong'); title.textContent = share.name; const detail = document.createElement('span'); detail.textContent = `${share.scope} - ${share.duration || 'duree non precisee'}`; main.append(title, detail); const revoke = document.createElement('button'); revoke.className = 'revoke'; revoke.dataset.person = share.name; revoke.dataset.shareId = share.id || ''; revoke.textContent = 'Revoquer'; row.append(avatar, main, revoke); $('#accessList').append(row);
}

function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 3200); }
