$('#fileInput').addEventListener('change', (e) => { if (e.target.files[0]) $('#fileName').textContent = e.target.files[0].name; });
function toBase64(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(new Error('Lecture du fichier impossible.')); reader.onload = () => resolve(String(reader.result).split(',')[1] || ''); reader.readAsDataURL(file); }); }
$('#uploadConfirm').addEventListener('click', async () => {
  const selectedFile = $('#fileInput').files[0];
  const name = selectedFile?.name || $('#documentType').value;
  const fileExtension = selectedFile?.name.split('.').pop().toUpperCase();
  const savedDocument = { name: name.replace(/\.[^.]+$/, ''), extension: ['JPG', 'JPEG', 'PNG'].includes(fileExtension) ? (fileExtension === 'JPEG' ? 'JPG' : fileExtension) : 'PDF' };
  if (selectedFile && !['application/pdf', 'image/jpeg', 'image/png'].includes(selectedFile.type)) { toast('Format non autorise : PDF, JPG ou PNG uniquement.'); return; }
  if (selectedFile && selectedFile.size > 10 * 1024 * 1024) { toast('Le document depasse la limite de 10 Mo.'); return; }
  const token = localStorage.getItem('halvethApiToken');
  if (token) { try { const contentBase64 = selectedFile ? await toBase64(selectedFile) : ''; await apiCall('/documents', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ name: savedDocument.name, type: $('#documentType').value, contentBase64, mimeType: selectedFile?.type || '' }) }); } catch (error) { toast(error.message); return; } }
  const row = document.createElement('article');
  row.className = 'document-row';
  row.innerHTML = `<span class="file-icon pdf">PDF</span><div class="doc-main"><strong>${name.replace(/\.[^.]+$/, '')}</strong><span>Ajouté à l'instant · En attente de vérification</span></div><span class="pending">● À vérifier</span><button class="more" aria-label="Options">•••</button>`;
  appendSavedDocument(savedDocument);
  writeLocalList(localDossierDocumentsKey, [...readLocalList(localDossierDocumentsKey), savedDocument]);
  refreshDossierCounts();
  toast('Document ajouté à votre coffre sécurisé.');
});

$('#shareConfirm').addEventListener('click', async () => {
  const name = $('#recipientName').value.trim(); if (!name) return;
  const scope = $('#shareScope').value;
  const duration = $('#shareDuration').value;
  const token = localStorage.getItem('halvethApiToken');
  let storedShare = null;
  if (token) { try { const result = await apiCall('/shares', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ name, scope, duration }) }); storedShare = result?.share || null; } catch (error) { toast(error.message); return; } }
  const applicationTitle = pendingRentalApplication?.title;
  const initials = name.split(/\s+/).map(x => x[0]).join('').slice(0,2).toUpperCase();
  const row = document.createElement('article'); row.className = 'access-row'; row.dataset.shareId = storedShare?.id || '';
  row.innerHTML = `<span class="avatar">${initials}</span><div><strong>${name}</strong><span>${scope} · Accès accordé</span></div><button class="revoke" data-person="${name}">Révoquer</button>`;
  row.querySelector('div span').textContent = `${scope} · ${duration}`;
  $('#accessList').append(row); writeLocalList(localDossierSharesKey, [...readLocalList(localDossierSharesKey), { name, scope, duration, initials }]); refreshDossierCounts();
  const activity = document.createElement('article'); activity.innerHTML = `<span class="activity-dot violet"></span><div><strong>Accès accordé à ${name}</strong><span>À l'instant · ${scope}</span></div>`; $('#historyList').prepend(activity);
  activity.querySelector('div span').textContent = `A l'instant · ${scope} · ${duration}`;
  if (pendingRentalApplication && name === pendingRentalApplication.contact && submitRentalApplication()) { toast(`Candidature envoyée pour ${applicationTitle}.`); } else { toast(`Accès sécurisé envoyé à ${name}.`); }
});

