$('#revokeConfirm').addEventListener('click', () => {
  if (!revokeTarget) return;
  const name = revokeTarget.querySelector('strong').textContent;
  const revoked = readLocalList(localDossierRevokedKey);
  if (!revoked.includes(name)) writeLocalList(localDossierRevokedKey, [...revoked, name]);
  writeLocalList(localDossierSharesKey, readLocalList(localDossierSharesKey).filter((share) => share.name !== name));
  refreshDossierCounts();
});
const locallyRevokedShares = readLocalList(localDossierRevokedKey);
$('#accessList').querySelectorAll('.access-row').forEach((row) => { if (locallyRevokedShares.includes(row.querySelector('strong').textContent)) row.remove(); });
readLocalList(localDossierDocumentsKey).forEach((document) => appendSavedDocument(document));
readLocalList(localDossierSharesKey).filter((share) => !locallyRevokedShares.includes(share.name)).forEach((share) => appendSavedShare(share));
refreshDossierCounts();

