function persistConversations() {
  const extras = defaultConversationIds.map((id) => ({ id, messages: conversations[id].messages.slice(defaultMessageCounts[id]) })).filter((entry) => entry.messages.length);
  const custom = Object.entries(conversations).filter(([id]) => !defaultConversationIds.includes(id)).map(([id, contact]) => ({ id, ...contact }));
  writeLocalList(localMessageExtrasKey, extras); writeLocalList(localNewConversationsKey, custom);
}
function conversationForRecipient(recipient, context = 'Échange privé') { const existing = Object.entries(conversations).find(([, contact]) => contact.name === recipient); if (existing) return existing[0]; const id = `api-${recipient.toLocaleLowerCase('fr').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'contact'}`; if (!conversations[id]) { const initials = recipient.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase(); conversations[id] = { name: recipient, role: context, initials, avatar: 'blue-avatar', messages: [] }; appendConversation(id); } return id; }
async function persistOutboundMessage(contactId, message, recipient, context) { const token = localStorage.getItem('halvethApiToken'); if (!token) return; try { const result = await apiCall('/messages', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ recipient, context, text: message.text }) }); if (result?.message) { message.id = result.message.id; persistConversations(); } } catch { /* Le message local reste disponible si le serveur est indisponible. */ } }
