function aiReplyFor(question) {
  const lower = question.toLocaleLowerCase('fr');
  if (lower.includes('annonce')) return 'Pour analyser une annonce, vérifiez d’abord l’identité ou le statut du bailleur, le montant et le détail des charges, la localisation exacte, les conditions de visite et toute demande de paiement anticipé. Gardez les échanges dans HALVETH et demandez les informations manquantes par écrit.';
  if (lower.includes('visite')) return 'Avant une visite, préparez une courte présentation, confirmez le créneau et demandez les éléments pratiques : état du logement, montant total mensuel, charges, dépôt de garantie, durée du bail, diagnostics disponibles et date de disponibilité.';
  if (lower.includes('dossier')) return 'Pour votre dossier, privilégiez les documents réellement demandés et évitez les informations non nécessaires. Dans Private Dossier, vous pourrez sélectionner chaque document, fixer une durée d’accès et révoquer le partage quand vous le souhaitez.';
  if (lower.includes('partag') || lower.includes('sécur')) return 'Le partage le plus sûr passe par Private Dossier : choisissez le destinataire, les documents utiles et une durée. Ne transmettez pas une pièce d’identité ou un justificatif sensible en pièce jointe dans une messagerie classique.';
  return 'Je peux vous aider à structurer cette démarche. Pour commencer, précisez si votre question concerne une annonce, une visite, votre dossier ou un échange avec un propriétaire. Je vous indiquerai les points utiles à vérifier, sans évaluer les personnes ni prendre de décision à votre place.';
}
