const candidateListingApplications = document.createElement('section'); candidateListingApplications.className = 'panel candidate-listing-applications'; candidateListingApplications.innerHTML = '<header class="panel-heading"><div><p class="eyebrow">MES CANDIDATURES HALVETH</p><h2>Gardez le fil de vos démarches.</h2><p>Chaque statut est factuel. Vos documents restent privés tant que vous ne choisissez pas un partage.</p></div><button class="text-button" id="refreshCandidateListingApplications">Actualiser</button></header><div class="candidate-listing-application-list" id="candidateListingApplicationList"><p>Connectez-vous pour retrouver vos candidatures envoyées sur HALVETH.</p></div>'; publicListingsPanel.insertAdjacentElement('afterend', candidateListingApplications);
function listingCard(listing) { const card = document.createElement('article'); card.className = 'match-card'; const copy = document.createElement('div'); const title = document.createElement('strong'); title.textContent = listing.name; const details = document.createElement('span'); details.textContent = `${listing.city} · ${listing.type} · ${listing.price} / mois`; copy.append(title, details); const action = document.createElement('button'); action.className = 'secondary-button apply-public-listing'; action.dataset.listingId = listing.id; action.textContent = 'Candidater'; card.append(copy, action); return card; }
async function refreshPublicListings() { try { const result = await apiCall('/listings'); const target = $('#publicListingResults'); target.replaceChildren(); if (!result?.listings?.length) { const empty = document.createElement('p'); empty.textContent = 'Aucune annonce publiée pour le moment.'; target.append(empty); return; } result.listings.forEach((listing) => target.append(listingCard(listing))); } catch { /* Les annonces publiées seront disponibles dès que la connexion est rétablie. */ } }
const listingConversationDialog = document.createElement('dialog');
