document.body.append(listingConversationDialog);
let activeListingConversation = null;
function listingConversationTime(value) { return new Intl.DateTimeFormat('fr-FR', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)); }
function renderListingConversation(messages) { const target = $('#listingConversationMessages'); target.replaceChildren(); if (!messages.length) { const empty = document.createElement('p'); empty.className = 'listing-conversation-empty'; empty.textContent = 'Commencez l’échange : aucun document ne sera partagé automatiquement.'; target.append(empty); return; } messages.forEach((message) => { const row = document.createElement('div'); row.className = `message-row${message.mine ? ' mine' : ''}`; const bubble = document.createElement('div'); bubble.className = 'bubble'; bubble.textContent = message.text; const time = document.createElement('span'); time.className = 'message-time'; time.textContent = listingConversationTime(message.createdAt); row.append(bubble, time); target.append(row); }); target.scrollTop = target.scrollHeight; }
async function refreshListingConversation() { if (!activeListingConversation) return; const token = localStorage.getItem(apiTokenKey); if (!token) return; const result = await apiCall('/listing-messages/list', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ applicationId: activeListingConversation.applicationId }) }); renderListingConversation(result?.messages || []); }
async function openListingConversation({ applicationId, listingName, otherName }) { const token = localStorage.getItem(apiTokenKey); if (!token) { showPage('login'); toast('Connectez-vous pour accéder à cet échange privé.'); return; } activeListingConversation = { applicationId, listingName, otherName }; $('#listingConversationTitle').textContent = listingName || 'Échange privé'; $('#listingConversationContext').textContent = otherName ? `Avec ${otherName} · visible uniquement par les personnes concernées.` : 'Visible uniquement par les personnes concernées par cette candidature.'; $('#listingConversationInput').value = ''; listingConversationDialog.showModal(); try { await refreshListingConversation(); } catch (error) { renderListingConversation([]); toast(error.message || 'Impossible de charger cet échange.'); } }
$('#closeListingConversation').addEventListener('click', () => listingConversationDialog.close());
listingConversationDialog.addEventListener('close', () => { activeListingConversation = null; });
$('#listingConversationForm').addEventListener('submit', async (event) => { event.preventDefault(); const text = $('#listingConversationInput').value.trim(); const token = localStorage.getItem(apiTokenKey); if (!text || !token || !activeListingConversation) return; const submit = $('#listingConversationForm button'); submit.disabled = true; try { const result = await apiCall('/listing-messages', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ applicationId: activeListingConversation.applicationId, text }) }); if (!result?.message) throw new Error('Le message n’a pas été envoyé.'); $('#listingConversationInput').value = ''; await refreshListingConversation(); } catch (error) { toast(error.message || 'Impossible d’envoyer ce message.'); } finally { submit.disabled = false; } });
function candidateListingStatus(status) { return status === 'reviewed' ? 'À suivre' : status === 'declined' ? 'Sans suite' : status === 'withdrawn' ? 'Retirée' : 'Demande envoyée'; }
function renderCandidateListingApplications(applications) { const list = $('#candidateListingApplicationList'); list.replaceChildren(); if (!applications.length) { const empty = document.createElement('p'); empty.className = 'candidate-listing-empty'; empty.textContent = 'Aucune candidature envoyée depuis une annonce HALVETH pour le moment.'; list.append(empty); return; } applications.forEach((application) => { const row = document.createElement('article'); row.className = 'candidate-listing-application-row'; const mark = document.createElement('span'); mark.className = `candidate-listing-status ${application.status === 'reviewed' ? 'sent' : ['declined', 'withdrawn'].includes(application.status) ? 'awaiting' : ''}`; mark.textContent = application.status === 'reviewed' ? '✓' : ['declined', 'withdrawn'].includes(application.status) ? '–' : '◷'; const copy = document.createElement('div'); const title = document.createElement('strong'); title.textContent = application.listingName; const details = document.createElement('small'); details.textContent = `${candidateListingStatus(application.status)} · candidature envoyée le ${new Intl.DateTimeFormat('fr-FR', { dateStyle: 'medium' }).format(new Date(application.createdAt))}`; copy.append(title, details); const actions = document.createElement('div'); actions.className = 'candidate-listing-actions'; const message = document.createElement('button'); message.className = 'secondary-button open-candidate-listing-conversation'; message.dataset.applicationId = application.id; message.dataset.listingName = application.listingName; message.textContent = application.status === 'withdrawn' ? 'Voir l’historique' : 'Ouvrir l’échange'; actions.append(message); if (['submitted', 'reviewed'].includes(application.status)) { const withdraw = document.createElement('button'); withdraw.className = 'text-button withdraw-candidate-listing'; withdraw.dataset.applicationId = application.id; withdraw.textContent = 'Retirer'; actions.append(withdraw); } else { const continueSearch = document.createElement('button'); continueSearch.className = 'text-button resume-candidate-search'; continueSearch.textContent = 'Voir d’autres annonces'; actions.append(continueSearch); } row.append(mark, copy, actions); list.append(row); }); }
async function syncCandidateListingApplications() { const token = localStorage.getItem(apiTokenKey); if (!token) return; try { const result = await apiCall('/listing-applications', { headers: { authorization: `Bearer ${token}` } }); if (Array.isArray(result?.applications)) renderCandidateListingApplications(result.applications); } catch { /* Les candidatures locales restent visibles dans Rental Space si la connexion est indisponible. */ } }
async function resumeCandidateSearch() { const token = localStorage.getItem(apiTokenKey); if (token) { try { await apiCall('/journey', { method: 'PUT', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ continuousSearch: true }) }); } catch (error) { toast(error.message || 'Impossible de reprendre votre recherche.'); return; } } applyOpportunityRouter(true); await refreshPublicListings(); showPage('locations'); toast('Votre recherche continue est active. Votre dossier reste privé.'); }
$('#publicListingResults').addEventListener('click', async (event) => { const conversationButton = event.target.closest('.open-listing-conversation'); if (conversationButton) { openListingConversation({ applicationId: conversationButton.dataset.applicationId, listingName: conversationButton.dataset.listingName, otherName: 'le responsable de l’annonce' }); return; } const button = event.target.closest('.apply-public-listing'); if (!button) return; const token = localStorage.getItem(apiTokenKey); if (!token) { showPage('login'); toast('Connectez-vous pour candidater. Votre dossier restera privé tant que vous ne le partagez pas.'); return; } try { const result = await apiCall('/listing-applications', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ listingId: button.dataset.listingId, message: '' }) }); if (!result?.application) throw new Error('La candidature n’a pas été enregistrée.'); button.className = 'secondary-button open-listing-conversation'; button.dataset.applicationId = result.application.id; button.dataset.listingName = result.application.listingName || button.closest('.match-card')?.querySelector('strong')?.textContent || 'Cette candidature'; button.textContent = 'Ouvrir l’échange'; await syncCandidateListingApplications(); toast(result.duplicate ? 'Candidature déjà enregistrée. Vous pouvez reprendre l’échange privé.' : 'Candidature enregistrée. Aucun document de votre Private Dossier n’a été transmis.'); } catch (error) { toast(error.message || 'Impossible de candidater à cette annonce.'); } });
$('#candidateListingApplicationList').addEventListener('click', async (event) => { const conversation = event.target.closest('.open-candidate-listing-conversation'); if (conversation) { openListingConversation({ applicationId: conversation.dataset.applicationId, listingName: conversation.dataset.listingName, otherName: 'le responsable de l’annonce' }); return; } const resume = event.target.closest('.resume-candidate-search'); if (resume) { await resumeCandidateSearch(); return; } const withdraw = event.target.closest('.withdraw-candidate-listing'); if (!withdraw) return; const token = localStorage.getItem(apiTokenKey); if (!token) return; withdraw.disabled = true; try { const result = await apiCall('/listing-applications/withdraw', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ applicationId: withdraw.dataset.applicationId }) }); if (!result?.application) throw new Error('La candidature n’a pas été retirée.'); await syncCandidateListingApplications(); toast('Candidature retirée. Vos documents ne sont pas modifiés.'); } catch (error) { toast(error.message || 'Impossible de retirer cette candidature.'); } finally { withdraw.disabled = false; } });
