const propertyTruth = document.createElement('section'); propertyTruth.className = 'property-truth'; propertyTruth.innerHTML = '<div><p class="eyebrow">PERMANENT PROPERTY IDENTITY · RIVOLI-75-001</p><h2>Les informations du logement gardent leur source.</h2><p>France · Paris 1er · Country Pack France <span>SIMULÉ</span>. Les connecteurs publics, diagnostics et règles locales seront à relier à des API et à valider juridiquement.</p></div><div class="truth-list"><p><b>Adresse</b><span>Document vérifié · 18 juin 2026</span></p><p><b>DPE</b><span>À connecter à une source officielle</span></p><p><b>Risques</b><span>À connecter à une source publique</span></p><label class="country-pack-control">Juridiction du logement<select id="propertyCountryPack"><option value="France">France · parcours de démonstration</option><option value="Belgique">Belgique · Country Pack à connecter</option><option value="Canada">Canada · Country Pack à connecter</option></select><small id="countryPackStatus">La langue de l’application ne change pas les règles applicables.</small></label></div>'; document.querySelector('#locations .rental-notice').insertAdjacentElement('beforebegin', propertyTruth);
