$('#submitLogin').addEventListener('click', async () => {
  const email = $('#loginEmail').value.trim().toLowerCase();
  if (!email || !$('#loginPassword').value.trim()) { toast('Saisissez votre e-mail et votre mot de passe pour continuer.'); return; }
  try {
    const account = await apiCall('/auth/login', { method: 'POST', body: JSON.stringify({ email, password: $('#loginPassword').value }) });
    if (!account?.token || !account?.user) { toast('Connexion momentanément indisponible. Aucun accès hors ligne n’est autorisé.'); return; }
    localStorage.setItem(apiTokenKey, account.token);
    const results = await Promise.all([syncApiDocuments(), syncApiShares(), syncApiAccessHistory(), syncApiJourney(), syncApiFacts(), syncApiRentalContext(), syncApiNextAction(), syncApiTrustRequests(), syncApiVisits(), syncApiApplications(), syncCandidateListingApplications(), syncApiMessages(), syncApiRentalLife(), syncApiObservations(), syncApiFutureAvailability(), syncApiSafeChanges(), syncApiRentalTransition(), syncApiTeamInvitations(), syncApiNotifications(), syncAccountAccess(), syncApiPersonalProfile(), syncApiPreferences(), syncApiPreferenceHistory(), syncAccountProfile()]);
    const accountProfile = results[results.length - 1]?.profile;
    const activeRole = accountProfile?.activeRole || 'tenant';
    const savedPersonalProfile = results[results.length - 3] || {};
    const profile = { firstName: savedPersonalProfile.firstName || account.user.firstName, lastName: savedPersonalProfile.lastName || 'Utilisateur', email: savedPersonalProfile.email || account.user.email, phone: savedPersonalProfile.phone || '', role: roleLabelFromKey(activeRole) };
    localStorage.setItem(prototypeProfileKey, JSON.stringify(profile));
    displayPrototypeProfile(profile);
    enterHalvethSpace(activeRole);
  } catch (error) { toast(error instanceof Error ? error.message : 'La connexion a échoué.'); }
});
