$('#adminReviewForm').addEventListener('submit', async (event) => { event.preventDefault(); const report = $('#adminReviewReport').value.trim(); const token = localStorage.getItem(apiTokenKey); if (!report || !token) return; const submit = $('#createAdminReview'); submit.disabled = true; try { const result = await apiCall('/admin-reviews', { method: 'POST', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ report }) }); if (!result?.review) throw new Error('Le contrôle n’a pas été créé.'); $('#adminReviewReport').value = ''; closeAdminReviewDialog(); await Promise.all([loadAdminAudit(), loadAdminOverview()]); toast('Contrôle administratif ouvert et ajouté au journal.'); } catch (error) { toast(error instanceof Error ? error.message : 'Impossible d’ouvrir ce contrôle.'); } finally { submit.disabled = false; } });
adminReviewDialog.querySelector('.close').addEventListener('click', (event) => { if (typeof adminReviewDialog.close !== 'function') { event.preventDefault(); closeAdminReviewDialog(); } });
function showAdminDataQueueDialog() { loadAdminDataQueue(); if (typeof adminDataQueueDialog.showModal === 'function') adminDataQueueDialog.showModal(); else { adminDataQueueDialog.setAttribute('open', ''); adminDataQueueDialog.classList.add('fallback-open'); } }
function closeAdminDataQueueDialog() { if (typeof adminDataQueueDialog.close === 'function') adminDataQueueDialog.close(); else { adminDataQueueDialog.removeAttribute('open'); adminDataQueueDialog.classList.remove('fallback-open'); } }
async function loadAdminDataQueue() { const token = localStorage.getItem(apiTokenKey); const target = $('#adminDataQueueList'); if (!token) return; try { const result = await apiCall('/admin/support-requests', { headers: { authorization: `Bearer ${token}` } }); const requests = (result?.requests || []).filter((request) => /export|donn[ée]es|confidentialit[ée]|suppression|effacement/i.test(`${request.topic} ${request.message}`)); target.replaceChildren(); if (!requests.length) { const empty = document.createElement('p'); empty.textContent = 'Aucune demande de données ou de confidentialité à traiter.'; target.append(empty); return; } requests.forEach((request) => { const row = document.createElement('article'); const dot = document.createElement('span'); dot.textContent = '•'; const copy = document.createElement('div'); const title = document.createElement('strong'); title.textContent = request.topic; const details = document.createElement('span'); details.textContent = `${request.status === 'resolved' ? 'Résolue' : request.status === 'in_progress' ? 'En cours' : 'À traiter'} · ${activityDate(request.createdAt)}`; copy.append(title, details); row.append(dot, copy); target.append(row); }); } catch (error) { target.replaceChildren(); const message = document.createElement('p'); message.textContent = error instanceof Error ? error.message : 'Impossible de charger les demandes.'; target.append(message); } }
adminDataQueueDialog.querySelector('.close').addEventListener('click', (event) => { if (typeof adminDataQueueDialog.close !== 'function') { event.preventDefault(); closeAdminDataQueueDialog(); } });
$('#openDataExportQueue').addEventListener('click', showAdminDataQueueDialog);
function showAdminAuditDialog() { loadAdminAudit(); if (typeof adminAuditDialog.showModal === 'function') adminAuditDialog.showModal(); else { adminAuditDialog.setAttribute('open', ''); adminAuditDialog.classList.add('fallback-open'); } }
function closeAdminAuditDialog() { if (typeof adminAuditDialog.close === 'function') adminAuditDialog.close(); else { adminAuditDialog.removeAttribute('open'); adminAuditDialog.classList.remove('fallback-open'); } }
async function loadAdminAudit() { const token = localStorage.getItem(apiTokenKey); const target = $('#adminAuditList'); if (!token) return; try { const result = await apiCall('/admin-reviews', { headers: { authorization: `Bearer ${token}` } }); const reviews = result?.reviews || []; target.replaceChildren(); if (!reviews.length) { const empty = document.createElement('p'); empty.textContent = 'Aucun contrôle ouvert pour le moment.'; target.append(empty); return; } reviews.forEach((review) => { const row = document.createElement('article'); const dot = document.createElement('span'); dot.textContent = '•'; const copy = document.createElement('div'); const title = document.createElement('strong'); title.textContent = review.report; const details = document.createElement('span'); details.textContent = `Statut : ${review.status === 'resolved' ? 'clôturé' : 'en cours de contrôle'} · ${activityDate(review.updatedAt || review.createdAt)}`; copy.append(title, details); row.append(dot, copy); if (review.status !== 'resolved') { const resolve = document.createElement('button'); resolve.type = 'button'; resolve.className = 'text-button admin-resolve-review'; resolve.dataset.reviewId = review.id; resolve.textContent = 'Clôturer'; row.append(resolve); } target.append(row); }); } catch (error) { target.replaceChildren(); const message = document.createElement('p'); message.textContent = error instanceof Error ? error.message : 'Impossible de charger le journal de contrôle.'; target.append(message); } }
$('#adminAuditList').addEventListener('click', async (event) => { const button = event.target.closest('.admin-resolve-review'); if (!button) return; const token = localStorage.getItem(apiTokenKey); if (!token) return; button.disabled = true; try { await apiCall('/admin-reviews', { method: 'PUT', headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ id: button.dataset.reviewId, status: 'resolved' }) }); await Promise.all([loadAdminAudit(), loadAdminOverview()]); toast('Contrôle clôturé et conservé dans le journal.'); } catch (error) { toast(error instanceof Error ? error.message : 'Impossible de clôturer ce contrôle.'); } finally { button.disabled = false; } });
adminAuditDialog.querySelector('.close').addEventListener('click', (event) => { if (typeof adminAuditDialog.close !== 'function') { event.preventDefault(); closeAdminAuditDialog(); } });
$('#openAdminAudit').addEventListener('click', showAdminAuditDialog);
