function refreshDashboardSummary() {
  const stats = document.querySelectorAll('.dashboard-stats article strong');
  if (stats.length < 3) return;
  const documents = $('#documentList').children.length;
  const accesses = $('#accessList').children.length;
  const visits = $('#plannedVisits').children.length;
  stats[0].textContent = documents;
  stats[1].textContent = accesses;
  stats[2].textContent = visits;
  $('#dashboard .today-card strong').textContent = visits;
  $('#dashboard .today-card p').textContent = `visite${visits > 1 ? 's' : ''} à préparer`;
}
refreshDashboardSummary();

